from datetime import datetime, timedelta, timezone
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import activity_sources
import categories
import config
import database
import test_uniclubs_sync as source_fixtures
import uniclubs_database
import uniclubs_user


NOW = datetime(2026, 11, 15, 18)
SOURCE_NOW = datetime(2026, 11, 15, 17, tzinfo=timezone.utc)
AFTER = datetime(2026, 11, 16, 14)
EVENT_ID = 'uniclubs:event-1'


class ActivitySourcesTests(unittest.TestCase):
    """Exercise the facade without network requests or the developer's actual database files."""

    def setUp(self):
        """Create a real temporary source file and a separate in-memory app profile."""
        temporary = tempfile.TemporaryDirectory()
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        for name, value in (
                ('UNICLUBS_DB_FILE', self.directory / 'public.sqlite'),
                ('UNICLUBS_USER_DB_FILE', self.directory / 'private' / 'user.sqlite')):
            replacement = patch.object(config, name, value)
            replacement.start()
            self.addCleanup(replacement.stop)
        self.connection = database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        database.init_db(self.connection)
        self.taxonomy = categories.load_taxonomy()
        categories.seed_categories(self.connection, self.taxonomy)
        self.user_id = database.complete_onboarding(
            self.connection, 'Alex', {'career'}, 'demo', now=NOW)
        public = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            uniclubs_database.init_db(public)
            uniclubs_database.sync_catalog(
                public, [source_fixtures.club_record()], [source_fixtures.event_record()],
                now=SOURCE_NOW)
        finally:
            public.close()

    def confirm(self):
        """Confirm the source fixture through the actual facade."""
        return activity_sources.save_interaction(
            self.connection, self.user_id, EVENT_ID, 'confirm', now=NOW)

    def rate(self):
        """Create genuine attendance feedback after the fixture's end."""
        self.confirm()
        activity_sources.save_interaction(
            self.connection, self.user_id, EVENT_ID, 'attended', now=AFTER)
        return activity_sources.save_interaction(
            self.connection, self.user_id, EVENT_ID, 'rate', rating=5, now=AFTER)

    def test_unknown_end_does_not_turn_an_estimate_into_pending_feedback(self):
        """A previously confirmed event with an unknown end must retain its plan, not prompt."""
        self.confirm()
        public = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            with public:
                public.execute('UPDATE events SET end_utc=NULL WHERE external_id=?', ('event-1',))
        finally:
            public.close()
        self.assertEqual(activity_sources.pending_feedback(self.connection, self.user_id, AFTER),
                         [])
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, EVENT_ID)['status'], 'confirmed')
        self.assertTrue(activity_sources.calendar_uncertain(
            self.connection, self.user_id, datetime(2026, 11, 16), datetime(2026, 11, 17)))
        self.assertFalse(activity_sources.calendar_uncertain(
            self.connection, self.user_id, datetime(2026, 11, 18), datetime(2026, 11, 19)))

    def test_uncertain_or_cancelled_schedule_excludes_saved_ratings_from_training(self):
        """Retain genuine feedback but do not train against a later-unknown or cancelled event."""
        self.rate()
        public = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            for statement in (
                    "UPDATE events SET publication_status='cancelled' WHERE external_id=?",
                    "UPDATE events SET publication_status='published', end_utc=NULL "
                    'WHERE external_id=?'):
                with public:
                    public.execute(statement, ('event-1',))
                self.assertEqual(activity_sources.training_examples(self.connection, AFTER), [])
        finally:
            public.close()
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, EVENT_ID)['rating'], 5)

    def test_unknown_feedback_time_is_not_available_training_history(self):
        """A nullable old feedback timestamp cannot prove eligibility before a cutoff."""
        self.rate()
        private = uniclubs_user.get_connection(config.UNICLUBS_USER_DB_FILE)
        try:
            owner = activity_sources.profile_key(self.connection, self.user_id)
            with private:
                private.execute('UPDATE plans SET answered_at=NULL WHERE owner=?', (owner,))
        finally:
            private.close()
        self.assertEqual(activity_sources.training_examples(self.connection, AFTER), [])
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, EVENT_ID)['rating'], 5)

    def test_events_are_read_from_the_independent_catalog(self):
        """Route source identities without inserting any legacy event, series or club."""
        events = activity_sources.load_events(datetime(2026, 11, 16), datetime(2026, 11, 17))
        self.assertEqual([event.event_id for event in events], [EVENT_ID])
        self.assertEqual(activity_sources.load_event(EVENT_ID).title, 'Example workshop')
        first, last = activity_sources.date_bounds()
        self.assertEqual(first, datetime(2026, 11, 16).date())
        self.assertEqual(last, first)
        for query in ('SELECT count(*) FROM events', 'SELECT count(*) FROM series',
                      'SELECT count(*) FROM clubs'):
            self.assertEqual(self.connection.execute(query).fetchone()[0], 0)

    def test_private_confirm_and_cancel_never_write_legacy_interactions(self):
        """Keep source plans private while retaining cancelled IDs for ICS recognition."""
        saved = self.confirm()
        self.assertEqual(saved['status'], 'confirmed')
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, EVENT_ID)['event_id'], EVENT_ID)
        activity_sources.save_interaction(
            self.connection, self.user_id, EVENT_ID, 'cancel', now=NOW)
        self.assertEqual(activity_sources.known_event_ids(self.connection, self.user_id),
                         {EVENT_ID})
        self.assertEqual(activity_sources.confirmed_events(
            self.connection, self.user_id, datetime(2026, 11, 16), datetime(2026, 11, 17)), [])
        self.assertEqual(self.connection.execute('SELECT count(*) FROM interactions').fetchone()[0],
                         0)

    def test_confirmed_events_follow_source_time_updates(self):
        """A shifted source occurrence must move its existing plan without losing ownership."""
        self.confirm()
        public = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            uniclubs_database.sync_catalog(
                public, [source_fixtures.club_record()],
                [source_fixtures.event_record(start_utc='2026-11-16T14:00:00Z',
                                              end_utc='2026-11-16T15:00:00Z')],
                now=SOURCE_NOW + timedelta(hours=1))
        finally:
            public.close()
        events = activity_sources.confirmed_events(
            self.connection, self.user_id, datetime(2026, 11, 16), datetime(2026, 11, 17))
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0].start, datetime(2026, 11, 16, 15))
        self.assertEqual(events[0].event_id, EVENT_ID)

    def test_missing_source_does_not_remove_a_known_time_confirmation(self):
        """Absence alone must not free the user's already confirmed interval."""
        self.confirm()
        public = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            with public:
                public.execute('UPDATE events SET source_missing=1')
        finally:
            public.close()
        events = activity_sources.confirmed_events(
            self.connection, self.user_id, datetime(2026, 11, 16), datetime(2026, 11, 17))
        self.assertEqual(len(events), 1)
        self.assertTrue(events[0].source_missing)

    def test_cancelled_or_multiday_source_is_not_a_continuous_busy_block(self):
        """Retain the plan record but avoid blocking time for a cancelled or multiweek offer."""
        self.confirm()
        public = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
        try:
            for updates in (
                    ('cancelled', '2026-11-16T12:00:00.000000Z'),
                    ('published', '2026-12-16T12:00:00.000000Z')):
                with public:
                    public.execute('UPDATE events SET publication_status=?, end_utc=?', updates)
                self.assertEqual(activity_sources.confirmed_events(
                    self.connection, self.user_id, datetime(2026, 11, 16),
                    datetime(2026, 11, 17)), [])
        finally:
            public.close()
        self.assertEqual(activity_sources.get_interaction(
            self.connection, self.user_id, EVENT_ID)['status'], 'confirmed')

    def test_source_favorites_enrich_profile_without_legacy_target_rows(self):
        """Independent series and club identities participate in normal favorite matching."""
        event = activity_sources.load_event(EVENT_ID)
        for kind, target in (('series', event.series_id), ('club', event.club_id)):
            activity_sources.set_favorite(self.connection, self.user_id, kind, target, True)
        profile = activity_sources.get_profile(self.connection, self.user_id)
        self.assertEqual(set(profile.favorite_kinds(event)), {'series', 'club'})
        self.assertEqual(self.connection.execute('SELECT count(*) FROM favorites').fetchone()[0], 0)
        activity_sources.set_favorite(
            self.connection, self.user_id, 'series', event.series_id, False)
        self.assertEqual(activity_sources.get_profile(
            self.connection, self.user_id).favorite_kinds(event), ['club'])

    def test_new_favorite_must_exist_in_the_public_catalog(self):
        """Reject invented targets before storing a private preference."""
        with self.assertRaises(ValueError):
            activity_sources.set_favorite(
                self.connection, self.user_id, 'series', 'uniclubs-series:missing', True)
        self.assertEqual(activity_sources.get_profile(
            self.connection, self.user_id).favorite_series_ids, set())

    def test_feedback_and_training_use_only_ended_available_attendance(self):
        """Pending feedback disappears after rating and supplies a genuine model example."""
        self.confirm()
        pending = activity_sources.pending_feedback(self.connection, self.user_id, AFTER)
        self.assertEqual(len(pending), 1)
        self.assertEqual(pending[0]['event_id'], EVENT_ID)
        self.assertEqual(activity_sources.training_examples(self.connection, AFTER), [])
        activity_sources.save_interaction(
            self.connection, self.user_id, EVENT_ID, 'attended', now=AFTER)
        before = activity_sources.get_rating_revision(self.connection)
        activity_sources.save_interaction(
            self.connection, self.user_id, EVENT_ID, 'rate', rating=5, now=AFTER)
        self.assertGreater(activity_sources.get_rating_revision(self.connection), before)
        self.assertEqual(activity_sources.pending_feedback(self.connection, self.user_id, AFTER),
                         [])
        examples = activity_sources.training_examples(self.connection, AFTER)
        self.assertEqual(len(examples), 1)
        self.assertEqual(examples[0]['rating'], 5)
        self.assertEqual(examples[0]['event'].event_id, EVENT_ID)
        self.assertEqual(examples[0]['profile'].user_id, self.user_id)
        self.assertEqual(activity_sources.training_examples(self.connection, NOW), [])
        averages = activity_sources.bundle_averages(self.connection, self.user_id, AFTER)
        self.assertEqual(averages[examples[0]['event'].bundle_key], 5)

    def test_other_profile_does_not_inherit_favorites_or_plans(self):
        """Separate owner tokens isolate source state even when both users use one catalog."""
        self.confirm()
        other = database.create_user(self.connection, 'Mara', now=NOW)
        self.assertNotEqual(activity_sources.profile_key(self.connection, self.user_id),
                            activity_sources.profile_key(self.connection, other))
        self.assertEqual(activity_sources.known_event_ids(self.connection, other), set())
        self.assertIsNone(activity_sources.get_interaction(self.connection, other, EVENT_ID))

    def test_profile_reset_cannot_reuse_an_old_private_owner(self):
        """Recycled user IDs after reset must receive a new token and no old source plans."""
        self.confirm()
        owner = activity_sources.profile_key(self.connection, self.user_id)
        database.reset_database(self.connection)
        categories.seed_categories(self.connection, self.taxonomy)
        replacement = database.complete_onboarding(
            self.connection, 'Alex', {'career'}, 'demo', now=NOW)
        self.assertEqual(replacement, self.user_id)
        self.assertNotEqual(activity_sources.profile_key(self.connection, replacement), owner)
        self.assertEqual(activity_sources.known_event_ids(self.connection, replacement), set())

    def test_clear_current_user_removes_only_the_current_private_owner(self):
        """Explicit app reset can clear the owner without erasing another user's plans."""
        self.confirm()
        other = database.create_user(self.connection, 'Mara', now=NOW)
        activity_sources.save_interaction(self.connection, other, EVENT_ID, 'confirm', now=NOW)
        activity_sources.clear_current_user(self.connection)
        self.assertEqual(activity_sources.known_event_ids(self.connection, self.user_id), set())
        self.assertEqual(activity_sources.known_event_ids(self.connection, other), {EVENT_ID})

    def test_profile_key_does_not_commit_unfinished_caller_changes(self):
        """Reject initial ownership creation without committing the caller's profile edits."""
        self.connection.execute('UPDATE users SET display_name=? WHERE id=?',
                                ('Changed', self.user_id))
        with self.assertRaises(ValueError):
            activity_sources.profile_key(self.connection, self.user_id)
        self.assertTrue(self.connection.in_transaction)
        self.connection.rollback()
        self.assertEqual(database.get_user_profile(self.connection, self.user_id).display_name,
                         'Alex')

    def test_profile_key_does_not_replace_an_owner_created_by_another_tab(self):
        """A stale missing-key read must not overwrite an already established private owner."""
        owner = activity_sources.profile_key(self.connection, self.user_id)
        with patch('activity_sources.database.get_setting', side_effect=[None, owner]):
            selected = activity_sources.profile_key(self.connection, self.user_id)
        self.assertEqual(selected, owner)
        self.assertEqual(database.get_setting(
            self.connection, f'uniclubs_profile_{self.user_id}'), owner)


if __name__ == '__main__':
    unittest.main()
